usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Audio.Voices.New(
		context.TODO(),
		openai.AudioVoiceNewParams{
			Name: "string",
			AudioSample: io.Reader(bytes.NewBuffer([]byte("Example data"))),
			Consent: "string",
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
